with filtered as (select *, case when device in ('desktop', 'mobile') then 'Tier 1' else 'Other' end as device_group, quarter(started_at) as started_at_quarter, coalesce(country, 'NONE') as country_clean from sessions where started_at >= date '2023-04-16'), enriched as (select *, cume_dist() over (partition by country order by started_at_quarter desc) as started_at_quarter_cume_dist, ntile(5) over (partition by browser order by started_at_quarter, id) as started_at_quarter_bucket, avg(started_at_quarter) over (order by started_at_quarter, id rows between 2 preceding and current row) as started_at_quarter_avg_2, dense_rank() over (partition by device order by started_at_quarter nulls first) as started_at_quarter_dense_rank from filtered), with_last as (select s.*, x.web_event_page, x.web_event_duration_sec from enriched s left join lateral (select c.page as web_event_page, c.duration_sec as web_event_duration_sec from web_events c where c.session_id = s.id order by c.duration_sec desc, c.id desc limit 1) x on true), gaps as (select *, case when lag(started_at) over (partition by browser order by started_at, id) is null or started_at > lag(started_at) over (partition by browser order by started_at, id) + interval '14' day then 1 else 0 end as is_new_session from with_last), sessionized as (select id, device, browser, started_at, started_at_quarter, country_clean, started_at_quarter_cume_dist, started_at_quarter_dense_rank, web_event_page, sum(is_new_session) over (partition by browser order by started_at, id rows between unbounded preceding and current row) as island_id from gaps), with_last_sessions as (select s.*, latest.web_event_duration_sec, latest.event_time from sessionized s left join lateral (select c.duration_sec as web_event_duration_sec, c.event_time from web_events c where c.session_id = s.id order by c.duration_sec desc, c.id desc limit 1) latest on true) select web_event_page, date_trunc('quarter', started_at) as quarter_start, round(avg(started_at_quarter_cume_dist), 2) as avg_started_at_quarter_cume_dist, round(sum(web_event_duration_sec) / nullif(count(case when web_event_page = '/home' then 1 end), 0), 2) as web_event_duration_sec_per_home, percent_rank() over (partition by web_event_page order by round(sum(web_event_duration_sec) / nullif(count(case when web_event_page = '/home' then 1 end), 0), 2) desc) as web_event_duration_sec_per_home_percent_rank from with_last_sessions group by web_event_page, date_trunc('quarter', started_at) order by quarter_start;
